+
+	function compute(v) {
+		console.log(v);
+		return { data: v, ready: true };
+	}
+
+	function fade(node) {
+		return {
+			duration: 100,
+			tick: (t) => {
+				node.style.opacity = String(t);
+			}
+		};
+	}
